def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 seen=set(); rects=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=5 or (r,c) in seen: continue
   stack=[(r,c)]; seen.add((r,c)); comp=[]
   while stack:
    y,x=stack.pop(); comp.append((y,x))
    for a,b in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==5:
      seen.add((a,b)); stack.append((a,b))
   y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
   if len(comp)==(y1-y0+1)*(x1-x0+1) and len(comp)>1: rects.append((len(comp),y0,x0,y1-y0+1,x1-x0+1))
 if not rects: return out
 _,ry,rx,dh,dw=max(rects)
 if h%(dh+2)==0 and w%(dw+2)==0:
  for y in range(1,h,dh+2):
   for x in range(1,w,dw+2):
    vals=[grid[a][b] for a in range(y,y+dh) for b in range(x,x+dw) if grid[a][b]]
    if not vals: continue
    col=max(set(vals),key=vals.count)
    if len(vals)==dh*dw and col==5: col=0
    for a in range(y,y+dh):
     for b in range(x,x+dw): out[a][b]=col
  return out
 for a in range(ry,ry+dh):
  for b in range(rx,rx+dw): out[a][b]=0
 colors={v for row in out for v in row if v}
 for col in colors:
  pts=[(r,c) for r in range(h) for c in range(w) if out[r][c]==col]
  y=min(r for r,c in pts); x=min(c for r,c in pts)
  for a in range(y,min(h,y+dh)):
   for b in range(x,min(w,x+dw)): out[a][b]=col
 return out

